# sgnano test application in Ruby -- mode 4: text + lowres + CLUT4 framebuffer. The status rows, the lowres demo and the test pattern (16 colors).
# The test application of the firmware (F10 in the filer). The screen mode is set once here and never changed.
# The music: WTF4CH.mid (the sample SMF) in the same folder as this script, repeated (m pauses and resumes it).
# Generated by scripts/make_testapp_rb.py (2026-10-17, the music 2026-10-18); edit that script, not this file.
# Keys: m music pause, t text on/off, pad move objects (A: middle), v speed 1/4 1/2 1, l lowres on/off, b BG planes, o objects, O object load test, S scroll, F font table, f bold font. q or ESC ends it.
M = Machine
MODE = 4
M.mode = MODE

# ---- text demo and status rows (src/app/status.c) ----
TA = M::TEXT_BG_TRANSPARENT
def tput(row, s, fg)                    # a row from column 2, padded to column 76 (no text of the previous frame is left)
  s = s[0, 74]
  M.text_put(2, row, s.ljust(74), M.tattr(fg, 0, TA))
end
def text_demo(help)
  M.text_clear(M::TEXT_CLEAR)           # transparent: the graphics show through
  M.text_put(2, 0, "sgnano  ABCabc012  ｱｲｳｴｵ  あいう漢字ＡＢＣ", M.tattr(15, 0, TA))
  16.times { |i| M.text_put(2 + i, 1, " ", M.tattr(0, i)) }   # the 16 colors as the background of blank cells
  M.text_put(19, 1, help[0, 59], M.tattr(7, 0, TA))
end
ROW_VIDEO = 3; ROW_FRAME = 4; ROW_SYS = 5; ROW_USB = 6; ROW_KBD = 8; ROW_ECHO = 9
ROW_MOUSE = 10; ROW_MSC = 12; ROW_PAD = 16; ROW_PADUI = 20
$echo = ""; $keys_n = 0
def status_video(v)
  tput(ROW_VIDEO, format("%-22s mode %-16s fb %-6s %d.%03dkHz %.2fHz", v[:timing], v[:mode_name], v[:fb],
                         v[:line_hz] / 1000, v[:line_hz] % 1000, v[:frame_hz]), 11)
end
def status_frame(v)
  pm = v[:pair_max]
  tput(ROW_FRAME, format("f%-8d ur%-5d st%-5d rc%-3d lt%d/%d  pair %d/%dus", v[:frames], v[:underrun], v[:fifo_stall],
                         v[:recover], v[:late_start], v[:late_render], pm[0], pm[1]), 11)
end
def status_sys(s)
  tput(ROW_SYS, format("up %ds  mem free %dK (max %dK)  ruby", s[:uptime], s[:mem_free] / 1024, s[:mem_largest] / 1024), 10)
end
def status_usb(s)
  tput(ROW_USB, format("usb dev %d hub %d  pad %d  reinit %d wedged %d", s[:usb_devices], s[:hubs], s[:pads],
                       s[:usb_reinit], s[:usb_wedged]), 10)
end
def status_kbd(s)
  l = s[:kbd_leds]
  tput(ROW_KBD, format("kbd %s %04X:%04X n=%-5d led %s%s%s", s[:keyboard] ? "ok " : "-- ", s[:kbd_vid], s[:kbd_pid], $keys_n,
                       l & 1 != 0 ? "N" : "-", l & 2 != 0 ? "C" : "-", l & 4 != 0 ? "S" : "-"), 14)
  tput(ROW_ECHO, $echo, 15)
end
def status_mouse
  m = M.mouse
  b = m[:buttons]
  tput(ROW_MOUSE, format("mouse %s  btn %s%s%s", m[:connected] ? "ok" : "--", b & 1 != 0 ? "L" : "-", b & 4 != 0 ? "M" : "-",
                         b & 2 != 0 ? "R" : "-"), 14)
  tput(ROW_MOUSE + 1, format("x %+7d  y %+7d  wheel %+5d", m[:x].clamp(-999999, 999999), m[:y].clamp(-999999, 999999),
                             m[:wheel].clamp(-999999, 999999)), 15)
end
def status_msc(k)
  d = M.storage(k)
  tput(ROW_MSC + k, d ? format("msc%d %s %s %dMB", k, d[:vendor], d[:product], d[:mb]) : "msc#{k} --", 10)
end
AXIS = %w[X Y Z Rx Ry Rz]
def status_pad(k, pd)
  if pd
    s = format("p%d %04X:%04X h%d", k, pd[:vid], pd[:pid], pd[:hat])
    pd[:axes].each_with_index { |a, i| s << format(" %s%+4d", AXIS[i], a) if a }
    n = pd[:buttons_n]
    if n > 0
      s << " "
      [n, 20].min.times { |i| s << ((pd[:buttons] >> i) & 1 == 1 ? ((i % 9) + 1).to_s : ".") }   # mruby has no Integer#[]
    end
    tput(ROW_PAD + k, s, 14)
  else
    tput(ROW_PAD + k, "p#{k} --", 14)
  end
end
$slow = 0
def status_tick                         # rows that change slowly: one a frame in turn; the frame, keyboard, mouse and pads every frame
  k = $slow % 11
  $slow += 1
  v = M.video_info; s = M.sys_info      # a Hash each, once a frame (fewer objects for the GC)
  if k == 0 then status_video(v)
  elsif k == 1 then status_sys(s)
  elsif k == 2 then status_usb(s)
  elsif k < 7 then status_msc(k - 3)
  end
  status_frame(v)
  status_kbd(s)
  status_mouse
  if s[:pads] > 0 || k >= 7 then 4.times { |p| pd = M.pad(p); status_pad(p, pd) if pd || k == 7 + p } end
end
def key_echo(c)                         # the keys typed, at the bottom of the keyboard rows
  $keys_n += 1
  $echo << (c >= 0x20 && c < 0x7F ? c.chr : ".")
  $echo = $echo[-60, 60] if $echo.size > 60
end

# ---- the keys at the bottom of the screen ----
KEY_ROW = 21                            # rows 21..27 of the terminal (the status rows end at 19, the pad row is 20)
def key_help(list)
  M.text_put(2, KEY_ROW, "-- keys " + "-" * 66, M.tattr(8, 0, TA))
  list.each_with_index do |(k, d), i|
    x = 2 + (i % 2) * 38; y = KEY_ROW + 1 + i / 2
    M.text_put(x, y, k.rjust(7), M.tattr(14, 0, TA))
    M.text_put(x + 8, y, d[0, 29], M.tattr(7, 0, TA))
  end
end

# ---- test pattern on the framebuffer (src/video/testpattern.c) ----
# upper half: 8 color bars (80 dots each). lower half: R, G, B and gray in 32 steps (120 lines each, 20 dots a step);
# CLUT4: the 16 palette colors (40 dots each) instead. A 1-dot white frame around
BARS = [[31, 31, 31], [31, 31, 0], [0, 31, 31], [0, 31, 0], [31, 0, 31], [31, 0, 0], [0, 0, 31], [0, 0, 0]]
def c8(v) = v * 255 / 31
def draw_pattern
  fb = M.fb
  bits = fb.bits_per_pixel
  if bits == 16
    col = ->(r, g, b) { M.rgb(c8(r), c8(g), c8(b)) }
    bar = BARS.map { |c| col.(*c) }
    grad = ->(band, v) { [col.(v, 0, 0), col.(0, v, 0), col.(0, 0, v), col.(v, v, v)][band] }
    border = col.(31, 31, 31)
  else
    BARS.each_with_index { |c, i| M.fb_palette(i, c8(c[0]), c8(c[1]), c8(c[2])) }
    bar = (0...8).to_a
    if bits == 8
      32.times do |v|
        M.fb_palette(8 + v, c8(v), 0, 0); M.fb_palette(40 + v, 0, c8(v), 0)
        M.fb_palette(72 + v, 0, 0, c8(v)); M.fb_palette(104 + v, c8(v), c8(v), c8(v))
      end
      M.fb_palette(136, 255, 255, 255)
      grad = ->(band, v) { 8 + band * 32 + v }
      border = 136
    else                                # CLUT4: 8..15 = 8 grays (black to white), the frame is color 0 (white)
      8.times { |i| v = c8(i * 31 / 7); M.fb_palette(8 + i, v, v, v) }
      border = 0
    end
  end
  8.times { |i| fb.fill_rect(i * 80, 0, 80, 240, bar[i]) }
  if bits == 4
    16.times { |i| fb.fill_rect(i * 40, 240, 40, 240, i) }
  else
    4.times { |band| 32.times { |v| fb.fill_rect(v * 20, 240 + band * 60, 20, 60, grad.(band, v)) } }
  end
  fb.rect(0, 0, 640, 480, border)
end

# ---- lowres demo (src/video/lrdemo.c) ----
# tiles: 0..255 = the font (a character a tile), 256.. = discs for the objects (64x64 at 256, 32x32 at 320, 16x16 at 336, 8x8 at 340)
LR = M.lowres
FONT8 = # the 8x8 font of the firmware (font128 "normal"), ' '..'~', 8 bytes a character, 1 bit a dot
  "00000000000000003030302020002000505000000000000050f8505050f850002078a07028f0200000c8d02058980000" \
  "60a040a0a890780020200000000000003040404040403000601010101010600020a8702070a82000002020f820200000" \
  "0000000000101020000000f80000000000000000000010000008102040800000708898a8c8887000206020202020f800" \
  "708808708080f800708808700888700030509090f8101000f88080f008887000708880f088887000f808102020202000" \
  "708888708888700070888878088870000030300000303000003030000030306010204080402010000000f800f8000000" \
  "402010081020400070880830200030007088a8a8b8807800708888f888888800f08888f08888f0007088808080887000" \
  "f08888888888f000f88080f08080f800f88080f080808000708880b888887800888888f8888888007020202020207000" \
  "08080808088870008890a0c0a0908800808080808080f80088d8a8888888880088c8c8a8989888007088888888887000" \
  "f08888f08080800070888888a8906800f08888f0888888007088807008887000f8202020202020008888888888887000" \
  "888888505020200088888888a8d8880088885020508888008888502020202000f80810204080f8007040404040407000" \
  "888850f820f8200070101010101070002050880000000000000000000000f80080402000000000000000689888887800" \
  "8080f0888888f0000000708880887000080878888888780000007088f8807800102020f82020200000007888887808f0" \
  "808080f08888880020002020202020000800080808080870808890a0e090880020202020202030000000f0a8a8a8a800" \
  "0000f08888888800000070888888700000b0c88888f0808000788888780808060000b8c080808000000078807008f000" \
  "2020f82020202000000088888888780000008888885020000000a8a8a8a85800000088502050880000888888780808f0" \
  "0000f8102040f80018202040202018002020200020202000c02020102020c000000040a810000000"
SPR = [340, 336, 320, 256]              # tile of the disc for the width 8, 16, 32, 64
SINT = Array.new(64) { |i| (127 * Math.sin(2 * Math::PI * i / 64)).to_i }
# BG0（目の荒いグリッド）を raster.sgx と同じように波打たせる（2026-10-30）。128 = 動かさない、振幅 96 画素
WAVE0 = Array.new(512) { |i| (128 + 96 * Math.sin(2 * Math::PI * i / 512)).to_i }.pack("C*")
$font_bold = false
def load_font(bold)
  LR.pattern(0, [128] * 64)             # tile 0: transparent
  (0x20..0x7E).each do |code|
    o = (code - 0x20) * 16
    data = []
    8.times do |y|
      r = FONT8[o + y * 2, 2].to_i(16)
      r |= r >> 1 if bold
      8.times { |x| data << (r & (0x80 >> x) != 0 ? 127 : 128) }   # the ink is color 127 (the brightest of the ramp), the rest transparent
    end
    LR.pattern(code, data)
  end
end
def ramp(pal, r, g, b)                  # colors 0..127 from dark to bright
  128.times { |c| LR.palette(pal, c, r * 255 / 31 * c / 127, g * 255 / 31 * c / 127, b * 255 / 31 * c / 127) }
end
def disc(tile, size)                    # bright in the middle, darker to the edge, transparent outside
  c = size / 2; rr = c * c
  LR.pattern(tile, Array.new(size * size) { |i| x = i % size - c; y = i / size - c; d = x * x + y * y; d >= rr ? 128 : 127 - d * 127 / rr })
end
PLUS = "+".ord; DASH = "-".ord; BAR = "|".ord; SP = " ".ord
def grid_code(tx, ty)                   # BG0: a grid every 8 tiles (the right half is flipped horizontally, the lower half vertically)
  if tx % 8 == 0 then ty % 8 == 0 ? PLUS : BAR elsif ty % 8 == 0 then DASH else SP end
end
def grid_row(ty) = 64.times { |tx| LR.map(0, tx, ty, grid_code(tx, ty), 4, tx >= 32, ty >= 32) }
def build_bg0
  64.times { |ty| grid_row(ty) }
  $labels = {}
end
MSG = ["SGNANO LOWRES BG PLANE  ", "320x240 CLUT7 128COLORS ", "64x64 TILEMAP 8x8 TILE  ",
       "SCROLL WRAPS AT 512PIX  ", "PALETTE 64 x 128 COLORS ", "TWO CORES RENDER PAIRS  "]
# for each message and each position: the character, the character at the mirrored place in its word, and which word (-1 = a blank)
MSGW = MSG.map do |line|
  len = line.size
  Array.new(len) do |p|
    if line[p] == " " then [SP, SP, -1]
    else
      s = p; e = p
      s -= 1 while s > 0 && line[s - 1] != " "
      e += 1 while e + 1 < len && line[e + 1] != " "
      [line[p].ord, line[s + e - p].ord, (0...s).count { |i| line[i] != " " && (i == 0 || line[i - 1] == " ") }]
    end
  end
end
def build_map                           # BG1: the messages; each word in turn as is / mirrored / as is / upside down
  64.times do |ty|
    w = MSGW[ty % MSG.size]; len = w.size; pal = ty % 4
    64.times do |tx|
      c = w[(tx + ty) % len]
      k = c[2] < 0 ? 0 : (c[2] + ty) % 4
      if k == 1 then LR.map(1, tx, ty, c[1], pal, true, false)    # the whole word in a mirror
      else LR.map(1, tx, ty, c[0], pal, false, k == 3)
      end
    end
  end
  build_bg0
end
def build_font_table                    # the 16x16 font table on BG1 (no flip, no scroll)
  LR.fill_map(1, 0x20)
  hex = "0123456789ABCDEF"
  16.times { |n| LR.map(1, 3 + n * 2, 1, hex[n].ord, 1); LR.map(1, 1, 3 + n, hex[n].ord, 1) }
  16.times { |r| 16.times { |c| LR.map(1, 3 + c * 2, 3 + r, r * 16 + c, 0) } }
end
$obj_demo = 0; $obj_count = 24          # 0 = no objects, 1 = demo, 2 = load test
def setup_objects(heavy)
  n = heavy ? 128 : $obj_count
  128.times do |i|
    if i >= n then LR.obj_hide(i); next end
    k = heavy ? 3 : i % 4
    w = 8 << k
    LR.obj(i, 0, 0, SPR[k], w, w, 1 + i % 5, i % 3)
    LR.obj_move(i, 96 + (i % 8) * 4, 72 + (i / 8 % 8) * 4) if heavy   # the load test: 128 x 64x64 on the same place
  end
  LR.obj_visible = true
  $obj_demo = heavy ? 2 : 1
end
$pox = 0; $poy = 0                      # the pad moves the centre of the objects (2026-10-18)
# the speed of the objects (their own motion and the pad's): 1 / $odiv. v cycles 1/4 -> 1/2 -> 1 (2026-10-18: the old speed is 1, the default is 1/4)
$odiv = 4; $oph = 0.0; $olast = M.ms
def speed_key(c)
  return false unless c == "v".ord
  $odiv = $odiv == 1 ? 4 : $odiv / 2
  true
end
def pad_objects
  lx, ly = M.pad_stick(0, :left)
  dx, dy = M.pad_dir(0)
  vx = (lx != 0.0 ? lx * 4 : dx * 3) / $odiv.to_f   # the stick: the speed follows how far it is pushed; the cross key: 3 a frame (at 1x)
  vy = (ly != 0.0 ? ly * 4 : dy * 3) / $odiv.to_f
  $pox = ($pox + vx).clamp(-150, 150); $poy = ($poy + vy).clamp(-110, 110)
  ($pox = 0; $poy = 0) if M.pad_pressed?(0, M::PAD_A)   # A: back to the middle
end
def move_objects(ph)
  ox = $pox.to_i; oy = $poy.to_i
  $obj_count.times do |i|
    w = 8 << (i % 4)
    # 位相は小数のまま使い、SINT の間を線形に補間する（2026-10-30。1/4 速さでも 4 フレームごとの
    # 飛びにならない）。sin を毎フレーム呼ばないので Ruby でも軽い
    a = ph * (1 + (i & 3)) / 2.0 + i * 5
    b = ph * (1 + ((i >> 2) & 3)) / 3.0 + i * 11
    ai = a.to_i; af = a - ai
    bi = b.to_i; bf = b - bi
    sa = SINT[ai & 63] + (SINT[(ai + 1) & 63] - SINT[ai & 63]) * af
    sb = SINT[bi & 63] + (SINT[(bi + 1) & 63] - SINT[bi & 63]) * bf
    LR.obj_move(i, (160 - w / 2 + ox + sa * 140 / 127).round,
                   (120 - w / 2 + oy + sb * 100 / 127).round)
  end
end
# the timing and the mode at the top left, on BG0 (the text plane is not shown in mode 6). BG0 scrolls sideways, so the label is written
# from the leftmost visible column again whenever it moves
LABEL_ROW = 1
PADLAB_ROW = 6                          # mode 6: the pad under the label
$labels = {}                            # row -> [col, lines] written there (the label at the top, the key list at the bottom in mode 6)
def label_update(lines, row = LABEL_ROW)
  col = (($sx0 >> 3) + 1) & 63
  return if $labels[row] == [col, lines]
  (row...row + lines.size).each { |r| grid_row(r) }
  lines.each_with_index { |s, r| s[0, 31].each_char.with_index { |ch, i| LR.map(0, (col + i) & 63, row + r, ch.ord, 0) } }
  $labels[row] = [col, lines.dup]
end
def lowres_init(light)
  LR.bg_visible(0, false); LR.bg_visible(1, false); LR.obj_visible = false   # hidden while building (less load on the display)
  ramp(0, 31, 31, 31); ramp(1, 8, 31, 12); ramp(2, 31, 22, 6); ramp(3, 10, 18, 31); ramp(4, 31, 10, 10)   # white, green, orange, blue, red
  load_font(false)
  disc(256, 64); disc(320, 32); disc(336, 16); disc(340, 8)
  build_map
  $lr_on = true; $table = false; $scroll = true; $sx0 = 0
  if light                              # mode 3: BG0 only, no objects (see the note at the top)
    $bg = 1; show_bg
  else
    $bg = 3; show_bg
    setup_objects(false)
  end
end
$t0 = M.ms; $ph = 0; $wphase = 0; $wave_on = false
def lowres_tick(label)
  if $scroll && !$table
    $ph = (M.ms - $t0) * 60 / 1000      # 60 units a second (not a unit a frame: the frame rate differs by the timing)
    $sx0 = (512 - $ph / 4) & 511
    LR.scroll(1, $ph & 511, ($ph / 4) & 511)
    LR.scroll(0, $sx0, 0)
    LR.raster_wave(0, WAVE0, $wphase)    # BG0: a wave like raster.sgx (2026-10-30)
    $wphase = ($wphase + 1) % 512
    $wave_on = true
  elsif $wave_on
    LR.raster_clear                     # S / font table: stop the wave
    $wave_on = false
  end
  now = M.ms
  $oph += (now - $olast) * 60 / 1000.0 / $odiv   # the objects' own clock: 60 units a second at 1x
  $olast = now
  if $obj_demo == 1
    pad_objects
    move_objects($oph)
  end
  unless $table
    label_update(label)
    label_update($keylab, KEYLAB_ROW) if $keylab   # mode 6: the key list at the bottom
  end
end
def show_bg
  LR.bg_visible(0, $lr_on && $bg & 1 != 0 && !$table)
  LR.bg_visible(1, $lr_on && $bg & 2 != 0)
end
def lowres_key(c)                       # the keys of lrdemo_key (l b f F o O S)
  case c
  when "l".ord then $lr_on = !$lr_on; show_bg; LR.obj_visible = $lr_on && $obj_demo != 0
  when "b".ord then $bg = ($bg + 1) % 4; show_bg     # BG0 only -> BG1 only -> both -> none
  when "f".ord then $font_bold = !$font_bold; load_font($font_bold)
  when "F".ord
    $table = !$table
    if $table then build_font_table; LR.scroll(1, 0, 0) else build_map end
    show_bg
  when "o".ord
    if $obj_demo != 1 then $obj_count = 24; setup_objects(false)
    elsif $obj_count >= 128 then $obj_demo = 0; LR.obj_visible = false
    else $obj_count = [$obj_count * 2, 128].min; setup_objects(false)
    end
  when "O".ord
    if $obj_demo == 2 then $obj_demo = 0; LR.obj_visible = false else setup_objects(true) end
  when "S".ord then $scroll = !$scroll; $t0 = M.ms - $ph * 1000 / 60
  else return false
  end
  true
end

# ---- music (the sample SMF, Sound / SPEC_sound.md) ----
SONG = "WTF4CH.mid"
def music_start
  if File.exist?(SONG)
    Sound.play(SONG, true)
    puts "music: #{SONG} (#{Sound.length / 1000.0} s, repeated; m pauses)"
  else
    puts "music: #{SONG} is not in #{Dir.pwd} -- no music"
  end
rescue => e
  puts "music: #{e.class}: #{e.message}"
end
def music_key(c)
  return unless c == "m".ord && Sound.playing?
  Sound.paused? ? Sound.resume : Sound.pause
end

# ---- the pad (pad 0): what is pressed now, for the screen (2026-10-18) ----
PAD_NAMES = { M::PAD_X => "X", M::PAD_A => "A", M::PAD_B => "B", M::PAD_Y => "Y", M::PAD_LB => "LB", M::PAD_RB => "RB",
              M::PAD_LT => "LT", M::PAD_RT => "RT", M::PAD_BACK => "BACK", M::PAD_START => "START", M::PAD_LS => "LS", M::PAD_RS => "RS" }
$pad_on = false; $pad_chk = 0
def pad_line(short)
  if ($pad_chk += 1) % 30 == 1 then $pad_on = !M.pad(0).nil? end   # connected? (twice a second; M.pad makes a Hash)
  return short ? "PAD --" : "pad 0: not connected (the F310 needs the D switch)" unless $pad_on
  dx, dy = M.pad_dir(0)
  held = PAD_NAMES.select { |n, _| M.pad_button?(0, n) }.values.join(" ")
  sp = $odiv == 1 ? "1" : "1/#{$odiv}"
  return format("PAD %+d %+d %s %s", dx, dy, held, $lr_on.nil? ? "" : "V" + sp) if short
  lx, ly = M.pad_stick(0, :left); rx, ry = M.pad_stick(0, :right)
  format("pad 0: dir %+d %+d  left %+.2f %+.2f  right %+.2f %+.2f  %s%s", dx, dy, lx, ly, rx, ry, held,
         $lr_on.nil? ? "" : "  (speed #{sp})")
end
def pad_events                          # mode 0: the presses and releases to the UART log
  return unless $pad_on || ($pad_chk += 1) % 30 == 1 && ($pad_on = !M.pad(0).nil?)
  PAD_NAMES.merge(M::PAD_UP => "UP", M::PAD_DOWN => "DOWN", M::PAD_LEFT => "LEFT", M::PAD_RIGHT => "RIGHT").each do |n, name|
    puts "[testapp] pad 0 #{name} pressed" if M.pad_pressed?(0, n)
    puts "[testapp] pad 0 #{name} released" if M.pad_released?(0, n)
  end
end

# ---- main loop ----
music_start
M.text_visible = true
text_demo('m=music t=text pad=move v=speed l=lowres b=BG o=objects O=object S=scroll F=font f=bold q=quit')
4.times { |p| status_pad(p, nil) }
4.times { |k| status_msc(k) }
key_help([["m", "music pause / resume"], ["t", "text plane on / off"], ["pad", "move the objects (A: middle)"], ["v", "object speed 1/4, 1/2, 1"], ["l", "lowres on / off"], ["b", "BG planes (0, 1, both, none)"], ["o", "objects (24 .. 128, off)"], ["O", "object load test"], ["S", "scroll on / off"], ["F", "font table"], ["f", "bold font"], ["q / ESC", "quit"]])
draw_pattern
lowres_init(false)
quit = false
until quit
  while (c = M.key)
    if c == "q".ord then quit = true
    else
      music_key(c)
      key_echo(c)
      M.text_visible = !M.text_visible? if c == "t".ord
      speed_key(c) || lowres_key(c)
    end
  end
  $lab ||= begin v = M.video_info; [v[:timing].upcase, "MODE #{v[:mode_name].upcase}"] end
  lowres_tick($lab)
  status_tick
  tput(ROW_PADUI, pad_line(false), 11)
  M.vsync
end
LR.clear
Sound.stop
puts "bye"
